drafts.2:
h1{
  font-size: 32px;
  text-align: center;
  color: rgb(125, 125, 247);
}

p{
  text-align: center;
}

drafts.4:
ul{
  display: flex;
  list-style: none;
  gap: 10px;
}

a{
  text-decoration: none;
}
a:hover{
  text-decoration: underline;
}

drafts.5:
table{
  width: 100%;
}

th,
td{
  border: 1px solid #94a3b8;
}

th{
  background-color: #bfdbfe;
}

drafts.6:
form {
  background: #f1f5f9;
  padding: 16px;
  border-radius: 10px;
}

label {
  display: block;
  margin: 10px 0 4px;
}

input {
  width: 100%;
  padding: 8px;
  margin-bottom: 8px;
  border: 1px solid #94a3b8;
  border-radius: 5px;
}

button {
  padding: 9px 14px;
  background: #4f46e5;
  color: white;
  border: 0;
  border-radius: 5px;
}

drafts.7:
.card{
  max-width: 360px;
  margin: 20px auto;
  border-radius: 12px;
  box-shadow: 0 4px 12px #0f172a18;
  padding: 18px;
  background-color: white;
  border: 1px solid #0f172a18;


}

.card h2{
    color: rgb(108, 108, 235);
  }
